<body>

    <div class="container">
        <header>
            <h1>Thermal Properties of Matter</h1>
            <div class="subtitle">Heat Capacity & Specific Heat Capacity</div>
        </header>

        <!-- Introduction Section -->
        <section class="card">
            <div class="card-header">
                <div class="card-icon">📖</div>
                <div class="card-title">Introduction</div>
            </div>
            <div class="card-content">
                <p>When heat energy is transferred to or from an object, its temperature changes. However, the amount of temperature change depends on the object's substance and mass. Understanding how different materials respond to heat is crucial in fields ranging from engineering to meteorology.</p>
            </div>
        </section>

        <!-- Definition Section -->
        <section class="card">
            <div class="card-header">
                <div class="card-icon">📝</div>
                <div class="card-title">Quick Definition</div>
            </div>
            <div class="card-content">
                <p><strong>Heat Capacity</strong> is the amount of heat energy required to raise the temperature of an entire object by 1°C (or 1 K).</p>
                <br>
                <p><strong>Specific Heat Capacity</strong> is the amount of heat energy required to raise the temperature of <span class="highlight-term">1 kilogram</span> of a substance by 1°C (or 1 K).</p>
            </div>
        </section>

        <!-- Formula Section: Heat Capacity -->
        <section class="card formula-card" id="card-heat-capacity">
            <div class="card-header">
                <div class="card-icon">🧮</div>
                <div class="card-title">Formula: Heat Capacity</div>
            </div>
            <div class="card-content">
                <p>The heat capacity ($C$) of an object is defined as the ratio of the heat supplied to the object to the resulting temperature change.</p>

                <div class="formula-display" data-formula-id="1">
                    $$ C = \frac{Q}{\Delta T} $$
                </div>

                <div class="formula-actions">
                    <button class="btn btn-outline" onclick="explainFormula(1)">Explain Formula</button>
                </div>
            </div>
        </section>

        <!-- Formula Section: Specific Heat Capacity -->
        <section class="card formula-card" id="card-specific-heat">
            <div class="card-header">
                <div class="card-icon">⚗️</div>
                <div class="card-title">Formula: Specific Heat Capacity</div>
            </div>
            <div class="card-content">
                <p>The specific heat capacity ($c$) relates the heat energy ($Q$) to the mass ($m$) and the temperature change ($\Delta T$). This is often rearranged to calculate heat energy.</p>

                <div class="formula-display" data-formula-id="2">
                    $$ Q = mc\Delta T $$
                </div>

                <div class="formula-actions">
                    <button class="btn btn-outline" onclick="explainFormula(2)">Explain Formula</button>
                    <button class="btn btn-primary" onclick="openFormulaLab(2)">Open Formula Lab</button>
                </div>
            </div>
        </section>

        <!-- Comparison Table -->
        <section class="card">
            <div class="card-header">
                <div class="card-icon">📊</div>
                <div class="card-title">Key Differences</div>
            </div>
            <div class="card-content">
                <p>It is important not to confuse heat capacity with specific heat capacity.</p>
                <div class="table-responsive">
                    <table>
                        <thead>
                            <tr>
                                <th>Feature</th>
                                <th>Heat Capacity ($C$)</th>
                                <th>Specific Heat Capacity ($c$)</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td><strong>Definition</strong></td>
                                <td>Heat required to raise temp of an <em>object</em> by 1°C.</td>
                                <td>Heat required to raise temp of 1 <em>kg</em> of substance by 1°C.</td>
                            </tr>
                            <tr>
                                <td><strong>Depends on</strong></td>
                                <td>Mass AND Material</td>
                                <td>Material ONLY</td>
                            </tr>
                            <tr>
                                <td><strong>SI Unit</strong></td>
                                <td>Joules per Kelvin (J/K)</td>
                                <td>Joules per kg per Kelvin (J kg⁻¹ K⁻¹)</td>
                            </tr>
                            <tr>
                                <td><strong>Symbol</strong></td>
                                <td>Uppercase $C$</td>
                                <td>Lowercase $c$</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
        </section>

        <!-- Applications -->
        <section class="card">
            <div class="card-header">
                <div class="card-icon">💡</div>
                <div class="card-title">Real-world Applications</div>
            </div>
            <div class="card-content">
                <ul style="padding-left: 20px;">
                    <li style="margin-bottom: 10px;"><strong>Cooling Systems:</strong> Water is used in car radiators because it has a high specific heat capacity, allowing it to absorb large amounts of heat without a drastic temperature rise.</li>
                    <li style="margin-bottom: 10px;"><strong>Cooking:</strong> Aluminum pots heat up faster than iron pots because aluminum has a lower specific heat capacity.</li>
                    <li><strong>Sea Breezes:</strong> Land heats and cools faster than the ocean due to the difference in specific heat capacities between soil and water.</li>
                </ul>
            </div>
        </section>
    </div>

    <!-- Explanation Modal -->
    <div class="modal-overlay" id="explanationModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title">Formula Explanation</div>
                <button class="close-btn" onclick="closeModal('explanationModal')">&times;</button>
            </div>
            <div id="explanationContent">
                <!-- Content injected via JS -->
            </div>
        </div>
    </div>

    <!-- Formula Lab Modal -->
    <div class="modal-overlay" id="labModal">
        <div class="modal">
            <div class="modal-header">
                <div class="modal-title">Formula Lab: $Q = mc\Delta T$</div>
                <button class="close-btn" onclick="closeModal('labModal')">&times;</button>
            </div>
            <div class="explanation-text">
                <p>Calculate the heat energy required. Enter values below.</p>

                <div class="lab-input-group">
                    <label class="lab-label">Mass ($m$) in kg</label>
                    <input type="number" id="lab-mass" class="lab-input" placeholder="e.g. 2" oninput="calculateLab()">
                </div>

                <div class="lab-input-group">
                    <label class="lab-label">Specific Heat Capacity ($c$) in J/kg°C</label>
                    <input type="number" id="lab-shc" class="lab-input" placeholder="e.g. 4186 (Water)" oninput="calculateLab()">
                </div>

                <div class="lab-input-group">
                    <label class="lab-label">Temperature Change ($\Delta T$) in °C</label>
                    <input type="number" id="lab-dt" class="lab-input" placeholder="e.g. 10" oninput="calculateLab()">
                </div>

                <div class="lab-result-box">
                    <span>Heat Energy ($Q$)</span>
                    <span class="lab-result-value" id="lab-result">0 Joules</span>
                </div>
            </div>
        </div>
    </div>

    <!-- KaTeX JS -->
    <script src="https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.js"></script>

    <script>
        // Formula Database extracted during "rendering"
        const formulaDatabase = {
            1: {
                latex: "C = \\frac{Q}{\\Delta T}",
                title: "Heat Capacity",
                context: "Relates total heat to total temperature change of a specific object.",
                variables: [
                    { symbol: "C", meaning: "Heat Capacity (J/K)" },
                    { symbol: "Q", meaning: "Heat Energy Supplied (J)" },
                    { symbol: "ΔT", meaning: "Change in Temperature (K or °C)" }
                ]
            },
            2: {
                latex: "Q = mc\\Delta T",
                title: "Specific Heat Equation",
                context: "Used to calculate the heat energy absorbed or released by a substance of known mass.",
                variables: [
                    { symbol: "Q", meaning: "Heat Energy (Joules)" },
                    { symbol: "m", meaning: "Mass of substance (kg)" },
                    { symbol: "c", meaning: "Specific Heat Capacity (J/kg°C)" },
                    { symbol: "ΔT", meaning: "Temperature Change (°C)" }
                ]
            }
        };

        // Initialize KaTeX rendering
        document.addEventListener("DOMContentLoaded", () => {
            renderMath();
        });

        function renderMath() {
            const mathElements = document.querySelectorAll('.formula-display');
            mathElements.forEach(el => {
                katex.render(el.innerText.trim(), el, {
                    throwOnError: false,
                    displayMode: true
                });
            });
        }

        // Modal Logic
        function closeModal(modalId) {
            document.getElementById(modalId).classList.remove('active');
        }

        // Explanation Logic
        function explainFormula(id) {
            const data = formulaDatabase[id];
            const contentDiv = document.getElementById('explanationContent');

            let html = `
                <div class="formula-display" style="margin-bottom: 20px;">$$${data.latex}$$</div>
                <p style="margin-bottom: 15px;"><strong>Context:</strong> ${data.context}</p>
                <p><strong>Variables involved:</strong></p>
                <ul class="variable-list">
            `;

            data.variables.forEach(v => {
                html += `<li><span class="var-symbol">${v.symbol}</span> : ${v.meaning}</li>`;
            });

            html += `</ul>`;

            contentDiv.innerHTML = html;

            // Re-render KaTeX inside the modal
            katex.render(data.latex, contentDiv.querySelector('.formula-display'), {
                throwOnError: false,
                displayMode: true
            });

            document.getElementById('explanationModal').classList.add('active');
        }

        // Formula Lab Logic
        function openFormulaLab(id) {
            if(id !== 2) return; // Only implemented for the main formula in this demo
            // Reset inputs
            document.getElementById('lab-mass').value = '';
            document.getElementById('lab-shc').value = '';
            document.getElementById('lab-dt').value = '';
            document.getElementById('lab-result').innerText = '0 Joules';
            document.getElementById('labModal').classList.add('active');
        }

        function calculateLab() {
            const m = parseFloat(document.getElementById('lab-mass').value);
            const c = parseFloat(document.getElementById('lab-shc').value);
            const dt = parseFloat(document.getElementById('lab-dt').value);

            const resultEl = document.getElementById('lab-result');

            if (isNaN(m) || isNaN(c) || isNaN(dt)) {
                resultEl.innerText = '...';
                return;
            }

            const Q = m * c * dt;

            // Format number nicely
            let formattedQ = Q.toLocaleString(undefined, { maximumFractionDigits: 2 });
            resultEl.innerText = `${formattedQ} Joules`;
        }

        // Close modal when clicking outside
        window.onclick = function(event) {
            if (event.target.classList.contains('modal-overlay')) {
                event.target.classList.remove('active');
            }
        }
    </script>
</body>
</html>
